CREATE    VIEW [FO].[vwExchangeRates]
AS
SELECT 
	T1.[RECID],
	'rcs' AS [DataareaId],
	T2.[FROMCURRENCYCODE] AS [FromCurrency],
	T2.[TOCURRENCYCODE] AS [ToCurrency],
	T1.[VALIDFROM] AS [FromDate],
	T1.[VALIDTO] AS [ToDate],
	(
		CAST((
				SELECT CASE T2.EXCHANGERATEDISPLAYFACTOR
						WHEN 1
							THEN T1.EXCHANGERATE / 100
						WHEN 2
							THEN (T1.EXCHANGERATE / 100) * 10
						WHEN 3
							THEN T1.EXCHANGERATE
						WHEN 4
							THEN (T1.EXCHANGERATE / 100) * 1000
						WHEN 5
							THEN (T1.EXCHANGERATE / 100) * 10000
						END AS RATE
				) AS NUMERIC(32, 16))
		) AS [ExchangeRate],
	T2.EXCHANGERATEDISPLAYFACTOR AS [ConversionFactor],
	T3.[DESCRIPTION] AS [RateTypeDescription],
	T3.[NAME] AS [RateTypeName]
FROM [synapse_fo].[EXCHANGERATE] T1
CROSS JOIN [synapse_fo].[EXCHANGERATECURRENCYPAIR] T2
CROSS JOIN [synapse_fo].[EXCHANGERATETYPE] T3
WHERE (
		(
			(T1.EXCHANGERATECURRENCYPAIR = T2.RECID)
			AND (T1.PARTITION = T2.PARTITION)
			)
		AND (
			(T2.EXCHANGERATETYPE = T3.RECID)
			AND (T2.PARTITION = T3.PARTITION)
			)
		)
